        key: value
        for key, value in check.items()
        if key not in {"version", "classes"}
    }
    if post_preserved != preserved:
        raise RuntimeError("TOP_LEVEL_STATE_CHANGED")

    seen_new = set()
    for item in check.get("classes", [])[6:]:
